import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BWuWLRhz.js";const E=JSON.parse('{"title":"封裝與分發","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/dev-guide/packaging.md","filePath":"zh-TW/dev-guide/packaging.md","lastUpdated":1790965225000}'),n={name:"zh-TW/dev-guide/packaging.md"};function l(p,s,h,r,o,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="封裝與分發" tabindex="-1">封裝與分發 <a class="header-anchor" href="#封裝與分發" aria-label="Permalink to &quot;封裝與分發&quot;">​</a></h1><p>本章節詳細介紹 Lertaro 外掛模組組件的目錄結構規範、第三方相依庫打包、多語言 JSON 資源內嵌以及自動化建置發布流程。</p><h2 id="_1-外掛模組組件目錄結構" tabindex="-1">1. 外掛模組組件目錄結構 <a class="header-anchor" href="#_1-外掛模組組件目錄結構" aria-label="Permalink to &quot;1. 外掛模組組件目錄結構&quot;">​</a></h2><p>Lertaro 在啟動時會遞迴掃描應用程式根目錄下的 <code>Plugins\\</code> 資料夾。為了保持環境純淨並避免不同外掛模組之間的相依庫發生版本衝突，強烈建議為每個外掛模組建立專屬的子目錄：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lertaro/</span></span>
<span class="line"><span>├── Lertaro.App.exe</span></span>
<span class="line"><span>├── Lertaro.PluginSdk.dll</span></span>
<span class="line"><span>└── Plugins/</span></span>
<span class="line"><span>    └── MyCustomPlugin/</span></span>
<span class="line"><span>        ├── Lertaro.Plugins.MyCustomPlugin.dll   (外掛模組主組件)</span></span>
<span class="line"><span>        ├── ThirdParty.Managed.dll              (託管第三方相依)</span></span>
<span class="line"><span>        └── NativeLibrary.dll                   (原生 C/C++ 相依——平放)</span></span></code></pre></div><ul><li><strong>相依性自動探測</strong>：Lertaro 的組件載入器透過 <code>Assembly.LoadFrom</code> 機制載入主 DLL，.NET 執行階段會自動從該子目錄中解析並載入其同級相依庫，絕不會與其他外掛模組相互干擾。</li><li><strong>原生相依要放在 DLL 旁邊，而不是 <code>runtimes\\&lt;rid&gt;\\native</code> 之下</strong>：隨包的外掛模組專案都設定 <code>&lt;GenerateDependencyFile&gt;false&lt;/GenerateDependencyFile&gt;</code>，因此不會產生 <code>.deps.json</code>，執行階段也沒有可供解析 RID 子資料夾的相依清單可用。原生程式庫必須能在應用程式基礎目錄中被找到——所以請平放複製。這也是兩種架構要發布成個別產物、而非合併成單一安裝包的原因：那個平放的載入目錄只能由一種架構的原生複本佔用。</li><li><strong>原生檔案容錯</strong>：當組件掃描遇到非 .NET 的原生二進位檔（如 <code>e_sqlite3.dll</code>）時，載入器會以 <code>Debug</code> 層級記錄後繼續處理，而不會拋出誤報的 <code>Error</code>。</li></ul><h2 id="_2-自動化建置複製設定-postbuild" tabindex="-1">2. 自動化建置複製設定（PostBuild） <a class="header-anchor" href="#_2-自動化建置複製設定-postbuild" aria-label="Permalink to &quot;2. 自動化建置複製設定（PostBuild）&quot;">​</a></h2><p>在外掛模組工程的 <code>.csproj</code> 檔案中設定 <code>PostBuild</code> 目標，即可在每次編譯成功後把產物部署到 Lertaro 的偵錯目錄。以下範例正是本儲存庫內外掛模組專案實際的做法——請留意<strong>平放</strong>的複製目的地，以及<strong>給 Service 的第二份複製</strong>，別名提供者與翻譯提供者正是因此才能同時供索引器與介面使用：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\Service\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>若你的外掛模組在載入時需要第三方託管或原生相依，請在平行的 <code>&lt;Copy&gt;</code> 項目中把它們複製到同一個資料夾。</p><h2 id="_3-內嵌多語言資源檔案" tabindex="-1">3. 內嵌多語言資源檔案 <a class="header-anchor" href="#_3-內嵌多語言資源檔案" aria-label="Permalink to &quot;3. 內嵌多語言資源檔案&quot;">​</a></h2><p>若你的外掛模組實作了 <a href="./sdk/ui-extensions.html"><code>ITranslationProvider</code></a> 多語言介面，推薦將翻譯 JSON 檔案作為<strong>組件內嵌資源</strong>打包，避免因外部檔案遺失導致介面亂碼：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>檔案請依 <code>Resources/Translations/{culture}/{type}.json</code> 組織，其中 <code>{type}</code> 就是你在呼叫 <code>TranslationService.LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> 時傳入的 <code>typeName</code>。本儲存庫的每個外掛模組都使用固定檔名 <strong><code>Plugin.json</code></strong>（<code>Resources/Translations/zh-CN/Plugin.json</code>、<code>Resources/Translations/en-US/Plugin.json</code>……）並傳入 <code>&quot;Plugin&quot;</code>；<code>App.json</code> 不是外掛模組的慣例——它只存在於 CoreExtensions，因為該專案也提供宿主自己的介面字串。語系資料夾對應應用程式的七種介面語言，沒有對應資料夾的語系就直接退回呼叫端傳入的預設文字。</p><h2 id="_4-外掛模組版本與中繼資料定義" tabindex="-1">4. 外掛模組版本與中繼資料定義 <a class="header-anchor" href="#_4-外掛模組版本與中繼資料定義" aria-label="Permalink to &quot;4. 外掛模組版本與中繼資料定義&quot;">​</a></h2><p>在 <code>.csproj</code> 中定義外掛模組的版本號與組件資訊：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;針對特定業務系統的高效能即時檢索與動作擴充外掛模組。&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>該版本號與描述資訊會自動呈現在 Lertaro <strong>設定 → 外掛模組</strong> 的管理卡片中，方便使用者和開發者直觀核驗元件版本。</p><h2 id="_5-release-建置與架構產物" tabindex="-1">5. Release 建置與架構產物 <a class="header-anchor" href="#_5-release-建置與架構產物" aria-label="Permalink to &quot;5. Release 建置與架構產物&quot;">​</a></h2><p>在 Windows 上從儲存庫根目錄執行 <code>make.bat</code> 前，需要安裝 .NET SDK 和 <a href="https://jrsoftware.org/isdl.php#v7" target="_blank" rel="noreferrer">64 位元 Inno Setup 7</a>。就目前的情形而言，指令碼只會<strong>呼叫其建置常式一次，用於 x64</strong>，並產生：</p><ul><li><code>dist/</code> 中的 <code>Lertaro-Setup.exe</code> 與 <code>Lertaro-Portable.zip</code>。</li></ul><p>它的檔頭註解談到兩種架構（「x64 一如往常不帶 RID 發行；arm64 則是跨平台發行」），結尾橫幅也會印出 arm64 的路徑，但並沒有第二次 <code>:build_arch</code> 呼叫把 <code>ARCH=x64</code> 換成 <code>arm64</code>，所以本機執行不會建立 <code>Lertaro-Setup-arm64.exe</code> 或 <code>Lertaro-Portable-arm64.zip</code>——儘管發行工作流程確實照著這些檔名計算雜湊並上傳。在采信那個橫幅之前請先記住這點。arm64 安裝包與 x64 安裝包的差異只在 <code>Installer/installer.iss</code> 的 <code>ArchitecturesAllowed</code>（<code>arm64</code> 對比 <code>x64compatible</code>）加上 <code>SetupArchitecture=x64</code>；每個安裝包內的應用程式載荷都原生於各自的架構。請確保產物名稱與 <code>make.bat</code>、<code>Installer/installer.iss</code> 以及發行工作流程的資產清單保持一致。</p>`,22)])])}const c=i(n,[["render",l]]);export{E as __pageData,c as default};
